def sum_of_divisors(n):
    if n < 1:
        raise ValueError("n must be a positive integer")

    total = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            total += i
            complement = n // i
            if complement != i:
                total += complement
        i += 1

    return total
