def merge_intervals_with_weights(intervals):
    if not intervals:
        return {}

    # Sort intervals by start, then end
    sorted_intervals = sorted(intervals, key=lambda x: (x[0], x[1]))

    merged = []
    current_start, current_end, current_weight = sorted_intervals[0]

    for start, end, weight in sorted_intervals[1:]:
        if start <= current_end:  # Overlapping or touching
            current_end = max(current_end, end)
            current_weight += weight
        else:
            merged.append((current_start, current_end, current_weight))
            current_start, current_end, current_weight = start, end, weight

    merged.append((current_start, current_end, current_weight))

    # Create dictionary with keys sorted by start ascending
    result = {}
    for start, end, weight in merged:
        result[(start, end)] = weight

    return result
