def simulate_queue(operations):
    q = deque()
    for op in operations:
        if op[0] == 'enqueue':
            q.append(op[1])
        elif op[0] == 'dequeue':
            if q:
                q.popleft()
        elif op[0] == 'rotate':
            k = op[1]
            if len(q) > 1 and k > 0:
                k %= len(q)
                for _ in range(k):
                    q.append(q.popleft())
    return list(q)
