def count_common_pairs(groups):
    n = len(groups)
    if n < 2:
        return 0

    # Map each element to the list of set indices that contain it
    element_to_sets = {}
    for idx, group in enumerate(groups):
        for elem in group:
            element_to_sets.setdefault(elem, []).append(idx)

    # Use a set of pairs to avoid double counting
    common_pairs = set()
    for indices in element_to_sets.values():
        m = len(indices)
        if m < 2:
            continue
        for a in range(m):
            for b in range(a + 1, m):
                i, j = indices[a], indices[b]
                if i > j:
                    i, j = j, i
                common_pairs.add((i, j))

    return len(common_pairs)
