def parse_logfmt(text: str) -> list[dict]:
    import re

    result = []
    key_re = re.compile(r'^[A-Za-z0-9_]+$')

    for line in text.splitlines():
        if not line.strip():
            continue

        fields = []
        i = 0
        n = len(line)

        while i < n:
            # Skip spaces
            while i < n and line[i] == ' ':
                i += 1
            if i >= n:
                break

            # Parse key
            start_key = i
            while i < n and (line[i].isalnum() or line[i] == '_'):
                i += 1
            key = line[start_key:i]
            if not key or not key_re.match(key):
                raise ValueError(f"Invalid key at position {start_key} in line: {line!r}")

            if i >= n or line[i] != '=':
                raise ValueError(f"Missing '=' after key '{key}' in line: {line!r}")
            i += 1  # skip '='

            # Parse value
            if i < n and line[i] == '"':
                i += 1
                chars = []
                closed = False
                while i < n:
                    c = line[i]
                    if c == '\\':
                        i += 1
                        if i >= n:
                            raise ValueError(f"Invalid escape at end of line: {line!r}")
                        esc = line[i]
                        if esc == '"':
                            chars.append('"')
                        elif esc == '\\':
                            chars.append('\\')
                        elif esc == 'n':
                            chars.append('\n')
                        else:
                            raise ValueError(f"Invalid escape '\\{esc}' in line: {line!r}")
                        i += 1
                    elif c == '"':
                        closed = True
                        i += 1
                        break
                    else:
                        chars.append(c)
                        i += 1
                if not closed:
                    raise ValueError(f"Unterminated quote in line: {line!r}")
                value = ''.join(chars)
            else:
                start_val = i
                while i < n and line[i] != ' ':
                    if line[i] in ('=', '"'):
                        raise ValueError(f"Invalid character in unquoted value in line: {line!r}")
                    i += 1
                value = line[start_val:i]
                if not value:
                    raise ValueError(f"Empty unquoted value in line: {line!r}")

            fields.append((key, value))

            # After value, must be space or end
            if i < n and line[i] != ' ':
                raise ValueError(f"Expected space after value in line: {line!r}")

        result.append(dict(fields))

    return result
