def count_paths(r: int, c: int, blocked: list[tuple[int, int]]) -> int:
    blocked_set = set(blocked)

    # dp[i][j] = number of paths to cell (i, j)
    dp = [[0] * c for _ in range(r)]

    if (0, 0) in blocked_set:
        return 0

    dp[0][0] = 1

    for i in range(r):
        for j in range(c):
            if (i, j) in blocked_set:
                dp[i][j] = 0
                continue
            if i == 0 and j == 0:
                continue
            from_top = dp[i-1][j] if i > 0 else 0
            from_left = dp[i][j-1] if j > 0 else 0
            dp[i][j] = from_top + from_left

    return dp[r-1][c-1]
